class Solution {
    private final Map<Integer,List<TreeNode>> memo=new HashMap<>();
    public List<TreeNode> allPossibleFBT(int n){
        if(n%2==0)return new ArrayList<>();
        if(n==1)return new ArrayList<>(Arrays.asList(new TreeNode(0)));
        if(memo.containsKey(n))return memo.get(n);
        List<TreeNode> answer=new ArrayList<>();
        for(int leftCount=1;leftCount<n;leftCount+=2)for(TreeNode left:allPossibleFBT(leftCount))for(TreeNode right:allPossibleFBT(n-1-leftCount)){
            TreeNode root=new TreeNode(0);
            root.left=left;
            root.right=right;
            answer.add(root);
        }
        memo.put(n,answer);
        return answer;
    }
}

